package com.argument.exporttrial;

import com.argument.common.exception.*;
import com.argument.adjudication.AdjudicationService;
import com.argument.version.VersionJson;
import com.argument.version.port.VersionIdentity.Actor;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.*;
import java.time.*;
import java.util.*;
import org.springframework.context.annotation.Profile;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import static com.argument.adjudication.AdjudicationService.require;

@Service @Profile("(local | test) & !prod")
public class ExportTrialService {
    public static final List<String> CORE=List.of("ELEMENTS","RELATIONS","PARTICIPANTS","DICTIONARIES","VERSIONS","PROVENANCE");
    private final ExportTrialRepository store;private final ExportBundleBuilder bundles;private final TrialFileStore files;private final ObjectMapper mapper;private final GraphExportRenderer graphs;
    public ExportTrialService(ExportTrialRepository store,ExportBundleBuilder bundles,TrialFileStore files,ObjectMapper mapper,GraphExportRenderer graphs){this.store=store;this.bundles=bundles;this.files=files;this.mapper=mapper;this.graphs=graphs;}
    public void role(Actor actor,String permission){require((actor.role("ADMIN")||actor.role("TASK_CREATOR"))&&actor.permission(permission),ErrorCode.FORBIDDEN,"当前身份无导出权限");}
    public ObjectNode read(Actor actor,String id){role(actor,"EXPORT_RECORD_VIEW");var record=store.export(VersionJson.uuid(id),false);require(actor.role("ADMIN")||actor.id().equals(record.path("requestedById").asText()),ErrorCode.FORBIDDEN,"只能读取本人创建的导出记录");bundles.authorizeSources(actor,record);if(record.hasNonNull("fileId")){var file=store.file(record.path("fileId").asText());file.remove("storageKey");record.set("file",file);record.set("generatedMetadata",store.generated(file.path("id").asText()));}return record;}
    public ObjectNode list(Actor actor,String status,String format,int page,int size){role(actor,"EXPORT_RECORD_VIEW");require(status==null||Set.of("QUEUED","RUNNING","COMPLETED","FAILED").contains(status),ErrorCode.VALIDATION_ERROR,"无效导出状态");require(format==null||Set.of("JSON","XLSX","PNG","SVG").contains(format),ErrorCode.VALIDATION_ERROR,"无效导出格式");var visible=new ArrayList<ObjectNode>();for(var r:store.exports()){if(!actor.role("ADMIN")&&!actor.id().equals(r.path("requestedById").asText()))continue;try{bundles.authorizeSources(actor,r);}catch(BusinessException e){if(e.getErrorCode()==ErrorCode.FORBIDDEN)continue;throw e;}if((status==null||status.equals(r.path("status").asText()))&&(format==null||format.equals(r.path("format").asText())))visible.add(r);}visible.sort(Comparator.comparing((ObjectNode n)->n.path("requestedAt").asText()).reversed().thenComparing(n->n.path("id").asText()));var result=mapper.createObjectNode().put("total",visible.size());var items=result.putArray("items");visible.stream().skip((long)(page-1)*size).limit(size).forEach(r->{if(r.hasNonNull("fileId")){var file=store.file(r.path("fileId").asText());file.remove("storageKey");r.set("file",file);}items.add(r);});return result;}
    @Transactional public ObjectNode create(Actor actor,String key,ObjectNode command){return createInternal(actor,key,command,false);}
    @Transactional public ObjectNode createGraph(Actor actor,String key,ObjectNode command){return createInternal(actor,key,command,true);}
    private ObjectNode createInternal(Actor actor,String key,ObjectNode command,boolean graph){
        String operation=graph?"TRIAL_GRAPH_EXPORT":"EX02";
        role(actor,"EXPORT_CREATE");VersionJson.uuid(key);store.lockActor(actor.id());String hash=VersionJson.canonicalHash(command);String cached=store.receipt(actor.id(),operation,key,hash);if(cached!=null){var record=VersionJson.parse(mapper,files.decrypt(cached));bundles.authorizeSources(actor,record);if(record.hasNonNull("fileId")){var file=store.file(record.path("fileId").asText());file.remove("storageKey");record.set("file",file);record.set("generatedMetadata",store.generated(file.path("id").asText()));}return record;}
        require(command.path("finalVersionIds").isArray()&&!command.path("finalVersionIds").isEmpty()&&command.path("finalVersionIds").size()<=100,ErrorCode.VALIDATION_ERROR,"请选择 1–100 个已入库最终版");var ids=new TreeSet<String>();for(var id:command.path("finalVersionIds")){require(id.isTextual(),ErrorCode.VALIDATION_ERROR,"最终版 ID 无效");require(ids.add(VersionJson.uuid(id.asText())),ErrorCode.VALIDATION_ERROR,"最终版不可重复");}String format=command.path("format").asText();require((graph?Set.of("PNG","SVG"):Set.of("JSON","XLSX")).contains(format),ErrorCode.VALIDATION_ERROR,"格式与导出入口不匹配");require(command.path("include").isArray(),ErrorCode.VALIDATION_ERROR,"include 必须是数组");var includes=new TreeSet<>(CORE);for(var include:command.path("include")){require(include.isTextual()&&(CORE.contains(include.asText())||"ACTOR_DISPLAY_NAMES".equals(include.asText())),ErrorCode.VALIDATION_ERROR,"不支持的导出选项");includes.add(include.asText());}
        String now=VersionJson.now();var n=mapper.createObjectNode();VersionJson.stamp(n,actor.id(),now);n.put("sourceType",graph?"ARGUMENT_GRAPH_RENDER":"FINAL_ANNOTATION");n.put("validationMode","D_BRANCH_TRIAL");var sourceIds=n.putArray("finalVersionIds");ids.forEach(sourceIds::add);n.put("format",format);var selected=n.putArray("include");includes.forEach(selected::add);n.put("status","QUEUED").put("requestedById",actor.id()).put("requestedAt",now).putNull("completedAt").putNull("fileId").putNull("failureCode").putNull("failureMessage");var input=bundles.build(actor,n);require(input.toString().length()<=20_000_000,ErrorCode.VALIDATION_ERROR,"导出内容过大，请缩小范围");input.set("include",selected.deepCopy());if(graph){graphs.prepare(actor,n,input,bundles);n.put("rendererVersion",GraphExportRenderer.VERSION);n.put("renderInputDigest",VersionJson.canonicalHash(input.path("renderGraphs")));}n.set("sourceManifest",input.path("sourceManifest").deepCopy());var subject=mapper.createObjectNode().put("format",format);subject.set("sourceManifest",n.path("sourceManifest"));subject.set("include",selected);if(graph){subject.set("rendererVersion",n.path("rendererVersion"));subject.set("renderInputDigest",n.path("renderInputDigest"));}n.put("sourceDigest",VersionJson.canonicalHash(subject));store.insertExport(n,input);event(actor,operation,n.path("id").asText(),n,"QUEUED",now);store.receipt(actor.id(),operation,key,hash,files.encrypt(n.toString()));return n;
    }
    @Transactional public ObjectNode ticket(Actor actor,String id,boolean isFile,String key,ObjectNode command,String requestId){
        VersionJson.uuid(key);store.lockActor(actor.id());ObjectNode record,file;if(isFile){file=store.file(VersionJson.uuid(id));String export=store.fileExport(id);if(export==null){privateFile(actor,file);record=mapper.createObjectNode();record.putNull("id");record.putArray("finalVersionIds");record.putArray("sourceManifest");record.put("sourceDigest",file.path("sha256").asText());}else record=read(actor,export);}else{record=read(actor,id);require("COMPLETED".equals(record.path("status").asText())&&record.hasNonNull("fileId"),ErrorCode.EXPORT_NOT_READY,"导出尚未完成");file=store.file(record.path("fileId").asText());}require("AVAILABLE".equals(file.path("status").asText()),ErrorCode.FILE_UNAVAILABLE,"文件不可用");String op=(isFile?"F03:":"EX05:")+id,hash=VersionJson.canonicalHash(command);String cached=store.receipt(actor.id(),op,key,hash);if(cached!=null)return VersionJson.parse(mapper,files.decrypt(cached));
        String purpose=command.path("purpose").asText();require(!purpose.isBlank()&&purpose.length()<=500,ErrorCode.VALIDATION_ERROR,"下载目的需为 1–500 字符");String now=VersionJson.now(),expires=Instant.parse(now).plusSeconds(300).toString(),token=files.token();var d=mapper.createObjectNode();VersionJson.stamp(d,actor.id(),now);d.set("fileId",file.get("id"));d.set("exportId",record.get("id"));d.put("requestedById",actor.id()).put("purpose",purpose).put("issuedAt",now).put("expiresAt",expires).putNull("revokedAt").put("tokenDigest",VersionJson.sha256(token)).put("requestId",requestId);var event=event(actor,isFile?"F03":"EX05",d.path("id").asText(),record,"ISSUED",now,requestId);d.set("auditEventId",event.get("id"));store.download(d);var result=mapper.createObjectNode().put("fileId",file.path("id").asText()).put("downloadRecordId",d.path("id").asText()).put("expiresAt",expires).put("downloadToken",token).put("contentUrl","/api/v1/file-assets/"+file.path("id").asText()+"/content");store.receipt(actor.id(),op,key,hash,files.encrypt(result.toString()));return result;
    }
    @Transactional(readOnly=true) public Download content(Actor actor,String id,String token){
        VersionJson.uuid(id);require(token!=null&&token.matches("[A-Za-z0-9_-]{43}"),ErrorCode.DOWNLOAD_TOKEN_INVALID,"下载凭证无效");ObjectNode ticket;try{ticket=store.ticket(VersionJson.sha256(token));}catch(BusinessException e){throw new BusinessException(ErrorCode.DOWNLOAD_TOKEN_INVALID,"下载凭证无效");}
        require(actor.id().equals(ticket.path("requestedById").asText()),ErrorCode.DOWNLOAD_TOKEN_INVALID,"下载凭证不属于当前身份");require(id.equals(ticket.path("fileId").asText()),ErrorCode.DOWNLOAD_TOKEN_FILE_MISMATCH,"下载凭证与文件不匹配");require(!ticket.hasNonNull("revokedAt"),ErrorCode.DOWNLOAD_TOKEN_INVALID,"下载凭证已撤销");require(Instant.now().isBefore(Instant.parse(ticket.path("expiresAt").asText())),ErrorCode.DOWNLOAD_TOKEN_EXPIRED,"下载凭证已过期，请重新申请");var file=store.file(id);if(ticket.hasNonNull("exportId")){var record=read(actor,ticket.path("exportId").asText());require("COMPLETED".equals(record.path("status").asText())&&id.equals(record.path("fileId").asText()),ErrorCode.EXPORT_NOT_READY,"导出不可下载");}else privateFile(actor,file);require("AVAILABLE".equals(file.path("status").asText()),ErrorCode.FILE_UNAVAILABLE,"文件不可用");byte[] bytes;try{bytes=files.read(file.path("storageKey").asText());}catch(IllegalStateException e){throw new BusinessException(ErrorCode.FILE_UNAVAILABLE,"文件内容不可用");}require(bytes.length==file.path("sizeBytes").asLong()&&TrialFileStore.sha256(bytes).equals(file.path("sha256").asText()),ErrorCode.FILE_UNAVAILABLE,"文件完整性检查失败");return new Download(file.path("fileName").asText(),file.path("mimeType").asText(),bytes);
    }
    private void privateFile(Actor actor,ObjectNode file){require(actor.role("ADMIN")&&(actor.permission("DOCUMENT_MANAGE")||actor.permission("GUIDE_MANAGE"))&&actor.id().equals(file.path("createdById").asText()),ErrorCode.FORBIDDEN,"该未绑定业务的原件仅上传者可读取");}
    public record Download(String name,String mimeType,byte[] bytes){}
    public ObjectNode event(Actor actor,String operation,String objectId,ObjectNode record,String status,String now){return event(actor,operation,objectId,record,status,now,VersionJson.uuid());}
    public ObjectNode event(Actor actor,String operation,String objectId,ObjectNode record,String status,String now,String requestId){var n=mapper.createObjectNode();VersionJson.stamp(n,actor.id(),now);n.put("requestId",requestId).put("actorUserId",actor.id()).put("operationCode",operation).put("objectId",objectId).put("objectType",operation.equals("F03")||operation.equals("EX05")?"DownloadRecord":"ExportRecord").put("occurredAt",now).put("status",status);n.set("exportId",record.get("id"));n.set("finalVersionIds",record.path("finalVersionIds").deepCopy());n.set("sourceManifest",record.path("sourceManifest").deepCopy());n.set("sourceDigest",record.path("sourceDigest"));store.event(n);return n;}
}
